public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        return result;
    }
    boolean[] used = new boolean[nums.length];
    permuteRecursive(nums, used, new ArrayList<>(), result);
    return result;
}

private void permuteRecursive(int[] nums, boolean[] used, List<Integer> tempList, List<List<Integer>> result) {
    if (tempList.size() == nums.length) {
        result.add(new ArrayList<>(tempList));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue;
        used[i] = true;
        tempList.add(nums[i]);
        permuteRecursive(nums, used, tempList, result);
        used[i] = false;
        tempList.remove(tempList.size() - 1);
    }
}

public List<List<Integer>> permute(int[] nums) {
    backtrack(nums, new ArrayList<>(), new boolean[nums.length]);
    return result;
}

private void backtrack(int[] nums, List<Integer> tempList, boolean[] used) {
    if (tempList.size() == nums.length) {
        result.add(new ArrayList<>(tempList));
    } else {
        for (int i = 0; i < nums.length; i++) {
            if (used[i]) continue;
            used[i] = true;
            tempList.add(nums[i]);
            backtrack(nums, tempList, used);
            used[i] = false;
            tempList.remove(tempList.size() - 1);
        }
    }
}

public List<List<Integer>> permute(int[] nums) {
