        return result;
    }

private void backtrack(List<List<Integer>> result, List<Integer> tempList, int[] nums) {
        if (tempList.size() == nums.length) {
            result.add(new ArrayList<>(tempList));
        } else {
            for (int i = 0; i < nums.length; i++) {
                if (tempList.contains(nums[i])) continue; // element already used
                tempList.add(nums[i]);
                backtrack(result, tempList, nums);
                tempList.remove(tempList.size() - 1);
            }
        }
    }

public int findLargestSubstring(List<String> strings) {
    int maxLength = 0;

    for (String s1 : strings) {
        for (String s2 : strings) {
            if (s1.equals(s2)) {
                continue;
            }

            String reversedS1 = new StringBuilder(s1).reverse().toString();
            String reversedS2 = new StringBuilder(s2).reverse().toString();

            if (s2.contains(s1) || s2.contains(reversedS1) || s1.contains(s2) || s1.contains(reversedS2)) {
                maxLength = Math.max(maxLength, Math.max(s1.length(), s2.length()));
            }
        }
    }

    return maxLength;
}

