public int findLargestSubstring(List<String> strings) {
    int maxLength = 0;

    for (String str : strings) {
        int len = str.length();
        for (int i = 0; i < len; i++) {
            String forward = str.substring(i);
            String backward = new StringBuilder(str.substring(i)).reverse().toString();
            boolean foundForward = strings.stream().anyMatch(s -> s.contains(forward));
            boolean foundBackward = strings.stream().anyMatch(s -> s.contains(backward));
            if (foundForward || foundBackward) {
                maxLength = Math.max(maxLength, len - i);
            }
        }
    }

    return maxLength;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }

    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int count = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (!visited[i][j] && grid[i][j] == '@') {
                count++;
                dfs(grid, visited, i, j);
            }
        }
    }

    return count;
}

private static void dfs(char[][] grid, boolean[][] visited, int row, int col) {
    int[] dRow = {-1, 1, 0, 0};
    int[] dCol = {0, 0, -1, 1};

    visited[row][col] = true;

    for (int k = 0; k < 4; k++) {
        int newRow = row + dRow[k];
        int newCol = col + dCol[k];

        if (newRow >= 0 && newRow < grid.length && newCol >= 0 && newCol < grid[0].length
                && !visited[newRow][newCol] && grid[newRow][newCol] == '@') {
            dfs(grid, visited, newRow, newCol);
        }
    }
}

