public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    int startX = start[0];
    int startY = start[1];
    int endX = end[0];
    int endY = end[1];

    boolean[][] visited = new boolean[n][n];
    boolean[][] graph = new boolean[n][n];

    for (int[] path : paths) {
        int fromX = path[0];
        int fromY = path[1];
        int toX = path[2];
        int toY = path[3];
        graph[fromX][toX] = true;
        graph[fromY][toY] = true;
    }

    if (!bfs(graph, visited, startX, startY, endX, endY)) {
        return "cannot be travelled";
    }

    return "can be travelled";
}

private static boolean bfs(boolean[][] graph, boolean[][] visited, int startX, int startY, int endX, int endY) {
    int n = graph.length;
    int[] dx = {0, 0, 1, -1};
    int[] dy = {1, -1, 0, 0};

    Queue<int[]> queue = new LinkedList<>();
    queue.add(new int[]{startX, startY});
    visited[startX][startY] = true;

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        int x = current[0];
        int y = current[1];

        if (x == endX && y == endY) {
            return true;
        }

        for (int k = 0; k < 4; k++) {
            int newX = x + dx[k];
            int newY = y + dy[k];

            if (newX >= 0 && newX < n && newY >= 0 && newY < n && graph[x][newX] && graph[y][newY] && !visited[newX][newY]) {
                queue.add(new int[]{newX, newY});
                visited[newX][newY] = true;
            }
        }
    }

    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] grid = new boolean[n][n];
    for (int[] path : paths) {
        grid[path[0]][path[1]] = true;
    }

    Queue<int[]> queue = new LinkedList<>();
    boolean[][] visited = new boolean[n][n];
    queue.add(start);
    visited[start[0]][start[1]] = true;

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        int[] directions = {-1, 0, 1, 0, -1};
        for (int i = 0; i < 4; i++) {
            int newRow = current[0] + directions[i];
            int newCol = current[1] + directions[i + 1];
            if (newRow >= 0 && newRow < n && newCol >= 0 && newCol < n && !visited[newRow][newCol] && grid[newRow][newCol]) {
                queue.add(new int[]{newRow, newCol});
                visited[newRow][newCol] = true;
            }
        }
    }

    return "cannot be travelled";
}

