            int from = path[0];
            int to = path[1];
            graph[from].add(to);
            graph[to].add(from);
        }

        // Convert start and end coordinates to 1D indices
        int startIndex = start[0] * n + start[1];
        int endIndex = end[0] * n + end[1];

        // Use BFS to check if there is a path from start to end
        Set<Integer> visited = new HashSet<>();
        Queue<Integer> queue = new LinkedList<>();
        queue.add(startIndex);
        visited.add(startIndex);

        while (!queue.isEmpty()) {
            int current = queue.poll();

            if (current == endIndex) {
                return "can be travelled";
            }

            for (int neighbor : graph[current]) {
                if (!visited.contains(neighbor)) {
                    visited.add(neighbor);
                    queue.add(neighbor);
                }
            }
        }

        return "cannot be travelled";
    }

