public int minTime(int n, int[][] edges, boolean[] hasApple) {
        // Create an adjacency list to represent the tree
        List<List<Integer>> tree = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            tree.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            tree.get(edge[0]).add(edge[1]);
            tree.get(edge[1]).add(edge[0]);
        }

        // DFS to calculate the minimum time to collect all apples
        return dfs(0, -1, tree, hasApple) * 2;
    }

private int dfs(int node, int parent, List<List<Integer>> tree, boolean[] hasApple) {
        int totalTime = 0;

        // Recursively visit all children of the current node
        for (int child : tree.get(node)) {
            if (child == parent) {
                continue;
            }
            int time = dfs(child, node, tree, hasApple);
            if (time > 0 || hasApple[child]) {
                totalTime += time + 2;
            }
        }

        return totalTime;
    }

public int minTime(int n, int[][] edges, boolean[] hasApple) {
        List[] tree = new List[n];
        for (int i = 0; i < n; i++) {
            tree[i] = new ArrayList<>();
        }
        for (int[] edge : edges) {
            tree[edge[0]].add(edge[1]);
            tree[edge[1]].add(edge[0]);
        }
        return dfs(0, -1, tree, hasApple) * 2;
    }

private int dfs(int node, int parent, List[] tree, boolean[] hasApple) {
        int time = 0;
        for (int neighbor : tree[node]) {
            if (neighbor == parent) continue;
            time += dfs(neighbor, node, tree, hasApple);
        }
        if ((time > 0 || hasApple[node]) && node != 0) {
            time += 2;
        }
        return time;
    }

