private int dfs(int node, int parent, boolean[] hasApple, List<List<Integer>> graph) {
        int time = 0;

        for (int neighbor : graph.get(node)) {
            if (neighbor == parent) continue;
            time += dfs(neighbor, node, hasApple, graph);
        }

        if ((node != 0 && time > 0) || hasApple[node]) {
            return time + 1;
        }

        return 0;
    }

public int minTime(int n, int[][] edges, boolean[] hasApple) {
        List<Integer>[] tree = new List[n];
        for (int i = 0; i < n; i++) {
            tree[i] = new ArrayList<>();
        }
        for (int[] edge : edges) {
            tree[edge[0]].add(edge[1]);
            tree[edge[1]].add(edge[0]);
        }
        return Math.max(0, dfs(0, -1, tree, hasApple) * 2);
    }

private int dfs(int node, int parent, List<Integer>[] tree, boolean[] hasApple) {
        int time = 0;
        for (int neighbor : tree[node]) {
            if (neighbor == parent) continue;
            int timeFromNeighbor = dfs(neighbor, node, tree, hasApple);
            if (timeFromNeighbor > 0 || hasApple[neighbor]) {
                time += timeFromNeighbor + 2;
            }
        }
        return time;
    }

public int minTime(int n, int[][] edges, boolean[] hasApple) {
        this.hasApple = hasApple;
        tree = new HashMap<>();
        visited = new HashSet<>();
        for (int i = 0; i < n; i++) {
            tree.put(i, new ArrayList<>());
        }
        for (int[] edge : edges) {
            tree.get(edge[0]).add(edge[1]);
            tree.get(edge[1]).add(edge[0]);
        }
        helper(0, -1);
        return time;
    }

private boolean helper(int node, int parent) {
        visited.add(node);
        boolean hasAppleHere = hasApple[node];
        for (int neighbor : tree.get(node)) {
            if (neighbor == parent || visited.contains(neighbor)) continue;
            if (helper(neighbor, node)) {
                hasAppleHere = true;
                time += 2;
            }
        }
        return hasAppleHere;
    }

public String sortString(String s) {
    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        count[c - 'a']++;
    }

    StringBuilder result = new StringBuilder();
    while (result.length() < s.length()) {
        // Step 1 to 3: Pick smallest characters
        for (int i = 0; i < 26; i++) {
            if (count[i] > 0) {
                result.append((char) (i + 'a'));
                count[i]--;
            }
        }

        // Step 4 to 6: Pick largest characters
        for (int i = 25; i >= 0; i--) {
            if (count[i] > 0) {
                result.append((char) (i + 'a'));
                count[i]--;
            }
        }
    }

    return result.toString();
}

