    for (int i = 0; i < n; i++) {
        for (int j = sum; j >= nums[i]; j--) {
            dp[i + 1][j] = dp[i][j] || dp[i][j - nums[i]];
        }
    }
    for (int i = 1; i <= n / 2; i++) {
        for (int j = 1; j <= sum / 2; j++) {
