        dp[0][0] = true;

        for (int i = 0; i < n; i++) {
            for (int j = n - 1; j >= 0; j--) {
                for (int k = 2 * n; k >= nums[i]; k--) {
                    dp[k][j + 1] = dp[k][j + 1] || dp[k - nums[i]][j];
                }
            }
        }

        for (int i = 1; i < 2 * n; i++) {
            for (int j = 1; j <= n; j++) {
                if (dp[i][j] && i * j == sum * j) {
                    return true;
                }
            }
        }

        return false;
    }

