public int minInsertions(String s) {
    int balance = 0;
    int insertions = 0;

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            balance++;
        } else {
            if (balance == 0) {
                insertions++;
            } else {
                balance--;
            }
        }
    }

    insertions += balance * 2;

    return insertions;
}

public int minInsertions(String s) {
    int left = 0, right = 0, pairs = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (right > 0) {
                pairs += right / 2;
                right %= 2;
            }
            left++;
        } else {
            right++;
            if (left > 0) {
                left--;
            } else {
                pairs++;
            }
        }
    }
    return pairs + left * 2 + right;
}

public int minInsertions(String s) {
