    int len = s.length();
    int insertions = 0;

    for (int i = 0; i < len; i++) {
        if (s.charAt(i) == '(') {
            if (right % 2 == 1) {
                insertions++;
                right--;
            }
            left++;
        } else {
            right++;
            if (i == len - 1 || s.charAt(i + 1) != ')') {
                insertions++;
            } else {
                i++;
            }
        }
    }

    return insertions + left % 2 + right % 2;
}

