public int findMinFibonacciNumbers(int k) {
    List<Integer> fib = new ArrayList<>();
    fib.add(1);
    fib.add(1);

    while (fib.get(fib.size() - 1) < k) {
        fib.add(fib.get(fib.size() - 1) + fib.get(fib.size() - 2));
    }

    int count = 0;
    for (int i = fib.size() - 1; i >= 0; i--) {
        if (k >= fib.get(i)) {
            k -= fib.get(i);
            count++;
        }
    }

    return count;
}

public int findMinFibonacciNumbers(int k) {
    List<Integer> fib = new ArrayList<>();
    fib.add(1);
    fib.add(1);

    //Generate Fibonacci numbers up to k
    while (fib.get(fib.size() - 1) < k) {
        fib.add(fib.get(fib.size() - 1) + fib.get(fib.size() - 2));
    }

    //Find the minimum number of Fibonacci numbers whose sum is equal to k
    int count = 0;
    int index = fib.size() - 1;
    while (k > 0) {
        if (k >= fib.get(index)) {
            k -= fib.get(index);
            count++;
        } else {
            index--;
        }
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    List<Integer> fib = new ArrayList<>();
    fib.add(1);
    fib.add(1);
    while (true) {
        int next = fib.get(fib.size() - 1) + fib.get(fib.size() - 2);
        if (next > k) break;
        fib.add(next);
    }

    int count = 0;
    int i = fib.size() - 1;
    while (k > 0) {
        if (fib.get(i) <= k) {
            k -= fib.get(i);
            count++;
        }
        i--;
    }
    return count;
}

public static int findMinFibonacciNumbers(int k) {
        List<Integer> fibonacci = new ArrayList<>();
        int a = 1, b = 1;
        fibonacci.add(a);
        while (b <= k) {
            fibonacci.add(b);
            int next = a + b;
            a = b;
            b = next;
        }

        int count = 0;
        for (int i = fibonacci.size() - 1; i >= 0; i--) {
            if (k >= fibonacci.get(i)) {
                k -= fibonacci.get(i);
                count++;
            }
        }

        return count;
    }

public int findMinFibonacciNumbers(int k) {
    List<Integer> fibNumbers = new ArrayList<>();
    int a = 1, b = 1;
    while (b <= k) {
        fibNumbers.add(b);
        int next = a + b;
        a = b;
        b = next;
    }
    int minCount = Integer.MAX_VALUE;
    backtrack(fibNumbers, k, 0, 0, minCount);
    return minCount;
}

private void backtrack(List<Integer> fibNumbers, int k, int currentSum, int count, int minCount) {
    if (currentSum == k) {
        minCount = Math.min(minCount, count);
        return;
    }
    if (currentSum > k || count >= minCount) {
        return;
    }
    for (int i = 0; i < fibNumbers.size(); i++) {
        backtrack(fibNumbers, k, currentSum + fibNumbers.get(i), count + 1, minCount);
    }
}

