public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    Arrays.fill(result, 'a'); // Initialize the array with 'a' to ensure lexicographically smallest
    k -= n; // Subtract n because each 'a' contributes 1 to the value

    for (int i = n - 1; i >= 0 && k > 0; i--) {
        int add = Math.min(25, k); // We can add at most 25 to make the character 'z'
        result[i] += add; // Add the value to the current character
        k -= add; // Subtract the added value from k
    }

    return new String(result);
}

public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
        k -= 1;
    }
    int remaining = k;
    for (int i = n - 1; i >= 0; i--) {
        if (remaining >= 25) {
            result[i] = 'z';
            remaining -= 25;
        } else {
            result[i] += remaining;
            break;
        }
    }
    return String.valueOf(result);
}

public String getSmallestString(int n, int k) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < n; i++) {
        int remainder = k - (n - i - 1);
        if (remainder <= 26) {
            sb.append((char)('a' + remainder - 1));
            k -= remainder;
        } else {
            sb.append('z');
            k -= 26;
        }
    }
    return sb.toString();
}

public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
        k--;
    }
    while (k > 0) {
        int index = n - 1;
        while (index >= 0 && result[index] == 'z') {
            index--;
        }
        if (index == -1) {
            return "z".repeat(k);
        }
        result[index]++;
        k--;
    }
    return new String(result);
}

public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder(n);
    for (int i = 0; i < n; i++) {
        if (k >= 26) {
            result.append('z');
            k -= 26;
        } else {
            result.append((char) ('a' + k - 1));
            k = 0;
        }
    }
    return result.reverse().toString();
}

