            if (lastDigit - 1 >= 0) {
                int prevNum = num * 10 + (lastDigit - 1);
                if (prevNum >= low && prevNum <= high) {
                    result.add(prevNum);
                    queue.offer(prevNum);
                }
            }
        }

        return result;
    }

