public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int longest = 0;

    // Arrays to store the counts of consecutive 1s
    int[][][] counts = new int[4][m][n]; // 0: horizontal, 1: vertical, 2: diagonal, 3: anti-diagonal

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                // Count horizontal line of 1s
                counts[0][i][j] = (j > 0 ? counts[0][i][j - 1] : 0) + 1;
                // Count vertical line of 1s
                counts[1][i][j] = (i > 0 ? counts[1][i - 1][j] : 0) + 1;
                // Count diagonal line of 1s
                counts[2][i][j] = (i > 0 && j > 0 ? counts[2][i - 1][j - 1] : 0) + 1;
                // Count anti-diagonal line of 1s
                counts[3][i][j] = (i > 0 && j < n - 1 ? counts[3][i - 1][j + 1] : 0) + 1;

                // Update the longest line length
                longest = Math.max(longest, counts[0][i][j]);
                longest = Math.max(longest, counts[1][i][j]);
                longest = Math.max(longest, counts[2][i][j]);
                longest = Math.max(longest, counts[3][i][j]);
            }
        }
    }

    return longest;
}

