    // Arrays to keep track of the lengths of lines
    int[] rowCount = new int[m];
    int[] colCount = new int[n];
    int[] diagCount = new int[m + n];
    int[] antiDiagCount = new int[m + n];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                // Horizontal count
                rowCount[i]++;
                // Vertical count
                colCount[j]++;
                // Diagonal count
                diagCount[i + j]++;
                // Anti-diagonal count
                antiDiagCount[i - j + n]++;

                maxLen = Math.max(maxLen, rowCount[i]);
                maxLen = Math.max(maxLen, colCount[j]);
                maxLen = Math.max(maxLen, diagCount[i + j]);
                maxLen = Math.max(maxLen, antiDiagCount[i - j + n]);
            } else {
                // Reset counts if current element is 0
                rowCount[i] = 0;
                colCount[j] = 0;
                diagCount[i + j] = 0;
                antiDiagCount[i - j + n] = 0;
            }
        }
    }

    return maxLen;
}

