public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }

    int N = A.length;
    int[] dp = new int[1 << N];
    dp[0] = 1;

    for (int mask = 0; mask < (1 << N); mask++) {
        int last = -1;
        for (int i = 0; i < N; i++) {
            if ((mask & (1 << i)) != 0) {
                last = i;
                break;
            }
        }

        for (int i = 0; i < last; i++) {
            if ((mask & (1 << i)) == 0) {
                int sum = A[i] + A[last];
                int root = (int) Math.sqrt(sum);
                if (root * root == sum) {
                    dp[mask | (1 << last)] += dp[mask ^ (1 << i)];
                }
            }
        }
    }

    return dp[(1 << N) - 1];
}

