    backtrack(0, new ArrayList<>(), A, count);
    return count;
}

private static void backtrack(int start, ArrayList<Integer> current, int[] A, int count) {
    if (current.size() == A.length && isSquareArray(current)) {
        count++;
        return;
    }

    for (int i = start; i < A.length; i++) {
        current.add(A[i]);
        backtrack(i + 1, current, A, count);
        current.remove(current.size() - 1);
    }
}

private static boolean isSquareArray(ArrayList<Integer> array) {
    for (int i = 0; i < array.size() - 1; i++) {
        int sum = array.get(i) + array.get(i + 1);
        if (!isPerfectSquare(sum)) {
            return false;
        }
    }
    return true;
}

