private static int countSquarePermutations(int[] A, int index, boolean[] used, int prevSum) {
    if (index == A.length) {
        return 1;
    }
    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if (!used[i] && isPerfectSquare(prevSum + A[i])) {
            used[i] = true;
            count += countSquarePermutations(A, index + 1, used, A[i]);
            used[i] = false;
        }
    }
    return count;
}

