    int index = 0;

    boolean up = true;

    for (int i = 0; i < rows + cols - 1; i++) {
        if (up) {
            int r = i < rows ? i : rows - 1;
            int c = i < rows ? 0 : i - rows + 1;
            while (r >= 0 && c < cols) {
                result[index++] = mat[r][c];
                r--;
                c++;
            }
        } else {
            int r = i < cols ? 0 : i - cols + 1;
            int c = i < cols ? i : cols - 1;
            while (r < rows && c >= 0) {
                result[index++] = mat[r][c];
                r++;
                c--;
            }
        }
        up = !up;
    }

    return result;
}

