    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int r = 0, c = 0, di = 1; // di changes between 1 and -1

    for (int i = 0; i < result.length; i++) {
        result[i] = mat[r][c];
        r += di;
        c -= di;

        if (r >= rows) {
            r = rows - 1;
            c += 2;
            di = -di;
        }
        if (c >= cols) {
            c = cols - 1;
            r += 2;
            di = -di;
        }
        if (r < 0) {
            r = 0;
            di = -di;
        }
        if (c < 0) {
            c = 0;
            di = -di;
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int length = digits.length;

    // Find the first digit that can be swapped to get a larger number
    int i;
    for (i = length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }

    // If no such digit is found, return -1
    if (i == -1) {
        return -1;
    }

    // Find the smallest digit on the right side of (i+1)th digit which is greater than digits[i]
    int j;
    for (j = length - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
            break;
        }
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Sort the digits after (i+1) in ascending order
    Arrays.sort(digits, i + 1, length);

    // Convert the character array back to an integer
    long result = Long.parseLong(new String(digits));

    // Check if the result is within the integer range
    if (result > Integer.MAX_VALUE) {
        return -1;
    }

    return (int) result;
}

public static int findSmallestInteger(int n) {
        ArrayList<Integer> digits = new ArrayList<>();

        // Extract digits and store them in a list
        while (n > 0) {
            digits.add(n % 10);
            n /= 10;
        }

        // Sort the digits in ascending order
        Collections.sort(digits);

        // Find the first non-ascending pair to swap
        int i;
        for (i = digits.size() - 2; i >= 0; i--) {
            if (digits.get(i) < digits.get(i + 1)) {
                break;
            }
        }

        // If no such pair is found, return -1
        if (i == -1) {
            return -1;
        }

        // Find the smallest digit greater than digits.get(i) to the right of it
        int j = digits.size() - 1;
        while (digits.get(j) <= digits.get(i)) {
            j--;
        }

        // Swap the digits
        Collections.swap(digits, i, j);

        // Reverse the digits after the original index i
        Collections.reverse(digits.subList(i + 1, digits.size()));

        // Reconstruct the number
        n = 0;
        for (int digit : digits) {
            n = n * 10 + digit;
        }

        return n;
    }

