public static List<String> centerSymmetricNumbers(int n) {
        List<String> result = new ArrayList<>();
        if (n <= 0) {
            return result;
        }
        helper(n, 0, result, new char[n]);
        return result;
    }

private static void helper(int n, int i, List<String> result, char[] current) {
        if (i == n / 2) {
            if (n % 2 == 0) {
                result.add(new String(current));
            } else {
                for (char c : new char[]{'0', '1', '8'}) {
                    if (current[0] != '0' || c != '0') {
                        current[i] = c;
                        result.add(new String(current));
                    }
                }
            }
            return;
        }

        for (char[] pair : new char[][]{{'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'}}) {
            if (i == 0 && pair[0] == '0' && current.length != 1) {
                continue;
            }
            current[i] = pair[0];
            current[n - 1 - i] = pair[1];
            helper(n, i + 1, result, current);
        }
    }

public static List<String> centerSymmetricNumbers(int n) {
        List<String> result = new ArrayList<>();
        helper(result, new char[n], 0, n - 1);
        return result;
    }

private static void helper(List<String> result, char[] current, int left, int right) {
        if (left > right) {
            result.add(String.copyValueOf(current));
            return;
        }
        char[] symmetricPairs = {'0', '1', '8'};
        if (left == right) {
            for (char num : symmetricPairs) {
                if (num != '0' || current.length != 1) {
                    current[left] = num;
                    result.add(String.copyValueOf(current));
                }
            }
        } else {
            for (char num : symmetricPairs) {
                if (left != 0 || num != '0') {
                    current[left] = num;
                    current[right] = getSymmetric(num);
                    helper(result, current, left + 1, right - 1);
                }
            }
        }
    }

private static char getSymmetric(char num) {
        char[] symmetricPairs = {'0', '1', '8', '6', '9'};
        char[] symmetricValues = {'0', '1', '8', '9', '6'};
        for (int i = 0; i < symmetricPairs.length; i++) {
            if (symmetricPairs[i] == num) {
                return symmetricValues[i];
            }
        }
        return num; // In case the input is not a symmetric pair, return the original character
    }

