        List<String> result = new ArrayList<>();
        if (n == 0) {
            return result;
        }
        helper(result, "", n, n);
        return result;
    }

private static void helper(List<String> result, String s, int left, int right) {
        if (left > right) {
            result.add(s);
            return;
        }
        if (left == right) {
            for (char c : new char[]{'0', '1', '8'}) {
                result.add(s + c);
                if (s.length() > 0) {
                    result.add(c + s + c);
                }
            }
            return;
        }
        if (left > 0) {
            for (char c : new char[]{'0', '1', '8', '6', '9'}) {
                helper(result, c + s + c, left - 1, right + 1);
            }
        }
    }

