        List<String> result = new ArrayList<>();
        if (n == 0) {
            return result;
        }
        if (n == 1) {
            result.add("0");
            result.add("1");
            result.add("8");
            return result;
        }
        List<String> middle = centerSymmetricNumbers(n - 2);
        for (String s : middle) {
            result.add("1" + s + "1");
            result.add("6" + s + "9");
            result.add("8" + s + "8");
            result.add("9" + s + "6");
        }
        if (n != 2) {
            result.remove(result.indexOf("0" + s + "0"));
        }
        return result;
    }

