public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i < 10; i++) {
        helper(i, n, result);
    }
    return result;
}

private static void helper(int current, int n, List<Integer> result) {
    if (current > n) return;
    result.add(current);
    for (int i = 0; i < 10; i++) {
        int next = current * 10 + i;
        if (next > n) return;
        helper(next, n, result);
    }
}

