public static int calculateUniqueSum(int[] nums) {
    int sum = 0;
    Map<Integer, Boolean> seen = new HashMap<>();
    for (int num : nums) {
        if (seen.containsKey(num)) {
            seen.put(num, false);
        } else {
            seen.put(num, true);
        }
    }
    for (Map.Entry<Integer, Boolean> entry : seen.entrySet()) {
        if (entry.getValue()) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

