    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = i; // Initialize with the maximum possible (i.e., i 1s of 1)
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1); // Update with the minimum of current value or 1 plus the minimum value of the remainder
        }
    }
    return dp[n];
}

